function requireDelivery(mode, attempt, chatId, text) {
  const good =
    attempt?.status === "sent" &&
    Number.isSafeInteger(attempt.messageId) &&
    attempt.messageId > 0 &&
    (text === undefined || attempt.text === text);
  if (good) return { chatId, status: "sent", messageId: attempt.messageId };
  const status = attempt?.status === "rejected" ? "rejected" : "unconfirmed";
  if (mode !== "daily")
    throw new Error("Telegram did not confirm the subscription message (" + status + ").");
  return {
    chatId,
    status,
    ...(Number.isInteger(attempt?.httpStatus) ? { httpStatus: attempt.httpStatus } : {}),
    ...(status === "unconfirmed"
      ? { reason: attempt?.reason ?? "message receipt did not match" }
      : {}),
  };
}

export default function dailyPhotoReceipts({ plan, recipes, previous, attempt }) {
  const state = previous
    ? {
        index: previous.index + 1,
        receipts: [
          ...previous.receipts,
          requireDelivery(plan.mode, attempt, recipes[previous.index].chatId),
        ],
      }
    : { index: 0, receipts: [] };
  const item = recipes[state.index];
  return { state, more: !!item, chatId: item?.chatId ?? 0, photo: item?.image ?? "unused" };
}

