function telegramEndpoint(botToken, method) {
  if (typeof botToken !== "string" || !/^\d{5,16}:[A-Za-z0-9_-]{20,100}$/.test(botToken)) {
    throw new Error("Bind the Telegram bot token as a secret variable.");
  }
  if (!["getMe", "sendPhoto", "sendMessage"].includes(method))
    throw new Error("Unknown Telegram recipe operation.");
  return "https://api.telegram.org/bot" + botToken + "/" + method;
}

async function telegramAttempt(context, botToken, method, payload, expectedBotId) {
  const url = telegramEndpoint(botToken, method);
  let response, body;
  try {
    response = await context.fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(payload),
      signal: context.signal,
    });
    body = await response.json();
  } catch (error) {
    if (context.signal?.aborted) throw new Error("Telegram delivery was cancelled.");
    if (response || ["http.http-failed", "http.limit-exceeded"].includes(error?.code))
      return { status: "unconfirmed", reason: "transport or response unavailable" };
    throw new Error("The Telegram HTTP request could not be processed.");
  }

  if (
    body?.ok === false &&
    Number.isInteger(body.error_code) &&
    [400, 401, 403, 404, 429].includes(response.status) &&
    body.error_code === response.status
  ) {
    return { status: "rejected", httpStatus: response.status };
  }
  if (response.status !== 200 || body?.ok !== true) {
    return {
      status: "unconfirmed",
      httpStatus: response.status,
      reason: "provider did not confirm delivery",
    };
  }
  const item = body.result;
  if (method === "getMe") {
    if (item?.is_bot !== true || !Number.isSafeInteger(item.id) || item.id < 1) {
      return { status: "unconfirmed", reason: "invalid bot identity" };
    }
    return { status: "verified", botId: item.id };
  }
  const mismatch =
    !Number.isSafeInteger(item?.message_id) ||
    item.message_id < 1 ||
    item.chat?.id !== payload.chat_id ||
    (item.from && item.from.id !== expectedBotId);
  if (mismatch)
    return { status: "unconfirmed", reason: "message receipt did not match the chat or bot" };
  return {
    status: "sent",
    messageId: item.message_id,
    ...(method === "sendMessage" ? { text: item.text } : {}),
  };
}

export default async ({ botId, token, welcome }, context) => {
  const result = await telegramAttempt(context, token, "getMe", {});
  if (
    result.status !== "verified" ||
    result.botId !== botId ||
    (welcome?.from?.id !== undefined && welcome.from.id !== botId)
  ) {
    throw new Error("Select the same Telegram bot account and token for all recipe steps.");
  }
  return { botId };
};

