export default function createSubscriber({ plan }) {
  if (plan.mode !== "subscription" || !plan.isNew || plan.recipients.length !== 1)
    throw new Error("Only a new subscription can be saved.");
  return { records: [{ fields: { chatid: plan.recipients[0].chatId, Name: plan.name } }] };
}

