export default function dailyLinkReceipts({
  plan,
  recipes,
  previous,
  attempt,
  photos,
  createdRecords,
}) {
  const state = previous
    ? {
        index: previous.index + 1,
        receipts: [
          ...previous.receipts,
          requireDelivery(
            plan.mode,
            attempt,
            recipes[previous.index].chatId,
            recipes[previous.index].text,
          ),
        ],
        subscription: previous.subscription,
      }
    : { index: 0, receipts: [], subscription: null };
  if (!previous) {
    if (photos.length !== recipes.length)
      throw new Error("All photo attempts must complete before the link loop.");
    if (plan.isNew) {
      const row = createdRecords?.[0];
      if (
        createdRecords.length !== 1 ||
        !row?.id ||
        Number(row.fields?.chatid) !== plan.recipients[0].chatId ||
        row.fields?.Name !== plan.name
      ) {
        throw new Error("The Airtable receipt does not match the new subscriber.");
      }
      state.subscription = row.id;
    }
  }
  const item = recipes[state.index];
  const html =
    item?.text.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;") ?? "unused";
  return { state, more: !!item, chatId: item?.chatId ?? 0, html, count: state.receipts.length };
}

